-- Create "oidc_states" table
CREATE TABLE "oidc_states" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "state" character varying NOT NULL, "verifier" character varying NOT NULL, "nonce" character varying NOT NULL, "redirect_to" character varying NOT NULL DEFAULT '/', "expires_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "oidc_states_state_key" to table: "oidc_states"
CREATE UNIQUE INDEX "oidc_states_state_key" ON "oidc_states" ("state");
-- Create "sources" table
CREATE TABLE "sources" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "type" character varying NOT NULL, "last_received_at" timestamptz NULL, "last_reconciled_at" timestamptz NULL, "last_error" character varying NULL, "last_error_at" timestamptz NULL, "received_total" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "sources_name_key" to table: "sources"
CREATE UNIQUE INDEX "sources_name_key" ON "sources" ("name");
-- Create "heartbeats" table
CREATE TABLE "heartbeats" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "key" character varying NOT NULL, "last_seen_at" timestamptz NULL, "expected_interval_seconds" bigint NOT NULL DEFAULT 60, "state" character varying NOT NULL DEFAULT 'unknown', "incident_id" bigint NULL, "last_ping_at" timestamptz NULL, "last_ping_error" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "heartbeats_key_key" to table: "heartbeats"
CREATE UNIQUE INDEX "heartbeats_key_key" ON "heartbeats" ("key");
-- Create "jobs" table
CREATE TABLE "jobs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "kind" character varying NOT NULL, "payload" jsonb NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "attempts" bigint NOT NULL DEFAULT 0, "max_attempts" bigint NOT NULL DEFAULT 5, "run_at" timestamptz NOT NULL, "locked_by" character varying NOT NULL DEFAULT '', "locked_until" timestamptz NULL, "last_error" text NOT NULL DEFAULT '', "unique_key" character varying NULL, "traceparent" character varying NOT NULL DEFAULT '', "finished_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "job_finished_at" to table: "jobs"
CREATE INDEX "job_finished_at" ON "jobs" ("finished_at");
-- Create index "job_status_run_at" to table: "jobs"
CREATE INDEX "job_status_run_at" ON "jobs" ("status", "run_at");
-- Create index "job_unique_key" to table: "jobs"
CREATE UNIQUE INDEX "job_unique_key" ON "jobs" ("unique_key") WHERE ((unique_key IS NOT NULL) AND ((status)::text = 'pending'::text));
-- Create "users" table
CREATE TABLE "users" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "email" character varying NOT NULL, "display_name" character varying NOT NULL DEFAULT '', "role" character varying NOT NULL DEFAULT 'viewer', "password_hash" character varying NULL, "oidc_issuer" character varying NULL, "oidc_subject" character varying NULL, "role_managed_by_oidc" boolean NOT NULL DEFAULT false, "disabled" boolean NOT NULL DEFAULT false, "last_login_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "user_oidc_issuer_oidc_subject" to table: "users"
CREATE UNIQUE INDEX "user_oidc_issuer_oidc_subject" ON "users" ("oidc_issuer", "oidc_subject");
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
-- Create "incidents" table
CREATE TABLE "incidents" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "title" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'open', "severity" character varying NOT NULL DEFAULT '', "grouping_key" character varying NOT NULL, "source" character varying NOT NULL DEFAULT '', "cluster" character varying NOT NULL DEFAULT '', "namespace" character varying NOT NULL DEFAULT '', "labels" jsonb NOT NULL, "verdict" character varying NOT NULL DEFAULT 'unknown', "summary" text NOT NULL DEFAULT '', "muted" boolean NOT NULL DEFAULT false, "mute_id" bigint NULL, "internal" boolean NOT NULL DEFAULT false, "opened_at" timestamptz NOT NULL, "acknowledged_at" timestamptz NULL, "resolved_at" timestamptz NULL, "closed_at" timestamptz NULL, "last_signal_at" timestamptz NOT NULL, "reopen_count" bigint NOT NULL DEFAULT 0, "notify_channels" jsonb NOT NULL, "notified_at" timestamptz NULL, "investigation_state" character varying NOT NULL DEFAULT 'none', "last_investigated_at" timestamptz NULL, "agent_conversation" jsonb NULL, "trace_id" character varying NOT NULL DEFAULT '', "assignee_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "incidents_users_assigned_incidents" FOREIGN KEY ("assignee_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "incident_grouping_key_status" to table: "incidents"
CREATE INDEX "incident_grouping_key_status" ON "incidents" ("grouping_key", "status");
-- Create index "incident_opened_at" to table: "incidents"
CREATE INDEX "incident_opened_at" ON "incidents" ("opened_at");
-- Create index "incident_status_last_signal_at" to table: "incidents"
CREATE INDEX "incident_status_last_signal_at" ON "incidents" ("status", "last_signal_at");
-- Create "actions" table
CREATE TABLE "actions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "type" character varying NOT NULL, "params" jsonb NOT NULL, "rationale" text NOT NULL DEFAULT '', "risk" character varying NOT NULL DEFAULT 'medium', "proposed_by" character varying NOT NULL, "proposer_id" bigint NULL, "investigation_id" bigint NULL, "status" character varying NOT NULL DEFAULT 'proposed', "decided_by_name" character varying NOT NULL DEFAULT '', "decided_via" character varying NOT NULL DEFAULT '', "decided_at" timestamptz NULL, "started_at" timestamptz NULL, "finished_at" timestamptz NULL, "expires_at" timestamptz NOT NULL, "output" text NOT NULL DEFAULT '', "error" text NOT NULL DEFAULT '', "idempotency_key" character varying NOT NULL, "summary" character varying NOT NULL DEFAULT '', "incident_id" bigint NOT NULL, "decided_by_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "actions_incidents_actions" FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "actions_users_decided_actions" FOREIGN KEY ("decided_by_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "action_incident_id" to table: "actions"
CREATE INDEX "action_incident_id" ON "actions" ("incident_id");
-- Create index "action_status_expires_at" to table: "actions"
CREATE INDEX "action_status_expires_at" ON "actions" ("status", "expires_at");
-- Create index "actions_idempotency_key_key" to table: "actions"
CREATE UNIQUE INDEX "actions_idempotency_key_key" ON "actions" ("idempotency_key");
-- Create "api_tokens" table
CREATE TABLE "api_tokens" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "name" character varying NOT NULL, "token_hash" character varying NOT NULL, "prefix" character varying NOT NULL, "role" character varying NOT NULL, "last_used_at" timestamptz NULL, "expires_at" timestamptz NULL, "revoked_at" timestamptz NULL, "user_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "api_tokens_users_tokens" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "api_tokens_token_hash_key" to table: "api_tokens"
CREATE UNIQUE INDEX "api_tokens_token_hash_key" ON "api_tokens" ("token_hash");
-- Create "channel_threads" table
CREATE TABLE "channel_threads" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "channel" character varying NOT NULL, "external_chat_id" character varying NOT NULL, "external_thread_id" character varying NOT NULL DEFAULT '', "card_message_id" character varying NOT NULL DEFAULT '', "card_hash" character varying NOT NULL DEFAULT '', "last_event_id" bigint NOT NULL DEFAULT 0, "incident_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "channel_threads_incidents_threads" FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "channelthread_channel_external_chat_id_external_thread_id" to table: "channel_threads"
CREATE INDEX "channelthread_channel_external_chat_id_external_thread_id" ON "channel_threads" ("channel", "external_chat_id", "external_thread_id");
-- Create index "channelthread_channel_incident_id" to table: "channel_threads"
CREATE UNIQUE INDEX "channelthread_channel_incident_id" ON "channel_threads" ("channel", "incident_id");
-- Create "channel_messages" table
CREATE TABLE "channel_messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "channel" character varying NOT NULL, "external_chat_id" character varying NOT NULL, "external_message_id" character varying NOT NULL, "kind" character varying NOT NULL, "timeline_event_id" bigint NULL, "action_id" bigint NULL, "hash" character varying NOT NULL DEFAULT '', "thread_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "channel_messages_channel_threads_messages" FOREIGN KEY ("thread_id") REFERENCES "channel_threads" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "channelmessage_action_id" to table: "channel_messages"
CREATE INDEX "channelmessage_action_id" ON "channel_messages" ("action_id");
-- Create index "channelmessage_channel_external_chat_id_external_message_id" to table: "channel_messages"
CREATE UNIQUE INDEX "channelmessage_channel_external_chat_id_external_message_id" ON "channel_messages" ("channel", "external_chat_id", "external_message_id");
-- Create "external_identities" table
CREATE TABLE "external_identities" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "channel_type" character varying NOT NULL, "external_id" character varying NOT NULL, "external_name" character varying NOT NULL DEFAULT '', "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "external_identities_users_identities" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "externalidentity_channel_type_external_id" to table: "external_identities"
CREATE UNIQUE INDEX "externalidentity_channel_type_external_id" ON "external_identities" ("channel_type", "external_id");
-- Create index "externalidentity_user_id_channel_type" to table: "external_identities"
CREATE UNIQUE INDEX "externalidentity_user_id_channel_type" ON "external_identities" ("user_id", "channel_type");
-- Create "investigations" table
CREATE TABLE "investigations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "trigger" character varying NOT NULL DEFAULT 'auto', "agent" character varying NOT NULL DEFAULT '', "model" character varying NOT NULL DEFAULT '', "analysis" text NOT NULL DEFAULT '', "summary" text NOT NULL DEFAULT '', "root_cause" text NOT NULL DEFAULT '', "verdict" character varying NOT NULL DEFAULT 'unknown', "confidence" double precision NOT NULL DEFAULT 0, "tool_calls" jsonb NULL, "prompt_tokens" bigint NOT NULL DEFAULT 0, "completion_tokens" bigint NOT NULL DEFAULT 0, "error" text NOT NULL DEFAULT '', "requested_by_id" bigint NULL, "started_at" timestamptz NULL, "finished_at" timestamptz NULL, "trace_id" character varying NOT NULL DEFAULT '', "incident_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "investigations_incidents_investigations" FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "investigation_incident_id_created_at" to table: "investigations"
CREATE INDEX "investigation_incident_id_created_at" ON "investigations" ("incident_id", "created_at");
-- Create index "investigation_status_started_at" to table: "investigations"
CREATE INDEX "investigation_status_started_at" ON "investigations" ("status", "started_at");
-- Create "link_codes" table
CREATE TABLE "link_codes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "code" character varying NOT NULL, "expires_at" timestamptz NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "link_codes_users_link_codes" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "link_codes_code_key" to table: "link_codes"
CREATE UNIQUE INDEX "link_codes_code_key" ON "link_codes" ("code");
-- Create "messages" table
CREATE TABLE "messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "role" character varying NOT NULL, "author_name" character varying NOT NULL DEFAULT '', "channel" character varying NOT NULL DEFAULT 'ui', "channel_name" character varying NOT NULL DEFAULT '', "content" text NOT NULL, "action_ids" jsonb NOT NULL, "reply_to_id" bigint NULL, "status" character varying NOT NULL DEFAULT 'done', "incident_id" bigint NOT NULL, "author_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "messages_incidents_messages" FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "messages_users_messages" FOREIGN KEY ("author_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "message_incident_id_created_at" to table: "messages"
CREATE INDEX "message_incident_id_created_at" ON "messages" ("incident_id", "created_at");
-- Create "mutes" table
CREATE TABLE "mutes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "matchers" jsonb NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "reason" text NOT NULL DEFAULT '', "created_by_name" character varying NOT NULL DEFAULT '', "incident_id" bigint NULL, "alertmanager_silence_id" character varying NOT NULL DEFAULT '', "alertmanager_source" character varying NOT NULL DEFAULT '', "expired_manually" boolean NOT NULL DEFAULT false, "created_by_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "mutes_users_mutes" FOREIGN KEY ("created_by_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "mute_ends_at" to table: "mutes"
CREATE INDEX "mute_ends_at" ON "mutes" ("ends_at");
-- Create "sessions" table
CREATE TABLE "sessions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "token_hash" character varying NOT NULL, "csrf_token" character varying NOT NULL, "expires_at" timestamptz NOT NULL, "last_seen_at" timestamptz NOT NULL, "user_agent" character varying NOT NULL DEFAULT '', "ip" character varying NOT NULL DEFAULT '', "auth_method" character varying NOT NULL DEFAULT 'local', "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "sessions_users_sessions" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "session_expires_at" to table: "sessions"
CREATE INDEX "session_expires_at" ON "sessions" ("expires_at");
-- Create index "sessions_token_hash_key" to table: "sessions"
CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions" ("token_hash");
-- Create "signals" table
CREATE TABLE "signals" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "source" character varying NOT NULL, "fingerprint" character varying NOT NULL, "status" character varying NOT NULL, "name" character varying NOT NULL DEFAULT '', "severity" character varying NOT NULL DEFAULT '', "cluster" character varying NOT NULL DEFAULT '', "namespace" character varying NOT NULL DEFAULT '', "labels" jsonb NOT NULL, "annotations" jsonb NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NULL, "generator_url" character varying NOT NULL DEFAULT '', "last_seen_at" timestamptz NOT NULL, "fire_count" bigint NOT NULL DEFAULT 1, "raw" jsonb NULL, "incident_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "signals_incidents_signals" FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "signal_incident_id_status" to table: "signals"
CREATE INDEX "signal_incident_id_status" ON "signals" ("incident_id", "status");
-- Create index "signal_source_fingerprint" to table: "signals"
CREATE UNIQUE INDEX "signal_source_fingerprint" ON "signals" ("source", "fingerprint");
-- Create index "signal_status_last_seen_at" to table: "signals"
CREATE INDEX "signal_status_last_seen_at" ON "signals" ("status", "last_seen_at");
-- Create "timeline_events" table
CREATE TABLE "timeline_events" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "type" character varying NOT NULL, "actor_type" character varying NOT NULL, "actor_id" bigint NULL, "actor_name" character varying NOT NULL DEFAULT '', "channel" character varying NOT NULL DEFAULT '', "channel_name" character varying NOT NULL DEFAULT '', "payload" jsonb NOT NULL, "trace_id" character varying NOT NULL DEFAULT '', "incident_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "timeline_events_incidents_timeline" FOREIGN KEY ("incident_id") REFERENCES "incidents" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "timelineevent_incident_id_id" to table: "timeline_events"
CREATE INDEX "timelineevent_incident_id_id" ON "timeline_events" ("incident_id", "id");
